sionDomState(page, baseline.domCache, signal);\n    const identity = chatGptNewTurnIdentity(\n      baseline.initialResponseTurnIdentities,\n      state.responseIdentities,\n    );\n    if (!identity) return \"\";\n    const locator = page.locator(`[data-testid=${JSON.stringify(identity)}], [data-chatgpt-search-unit-key=${JSON.stringify(identity)}]`);\n    return (await this.responseDomSnapshot(locator, {})).visibleText;\n  }\n\n  private async captureSubmissionBaseline(page: Page): Promise<ChatGptSubmissionBaseline> {\n    const userTurns = page.locator(CHATGPT_USER_TURN_SELECTOR);\n    const responseTurns = page.locator(CHATGPT_ASSISTANT_TURN_SELECTOR);\n    const domCache: ChatGptSubmissionDomCache = {};\n    const state = await this.submissionDomState(page, domCache);\n    return {\n      userTurns,\n      responseTurns,\n      initialUserTurnCount: state.userTurnCount,\n      initialResponseTurnCount: state.assistantTurnCount,\n      initialUserTurnIdentities: state.userIdentities,\n      initialResponseTurnIdentities: state.responseIdentities,\n      domCache,\n    };\n  }\n\n  /** True while the temporary-chat surface shows its visible \"Loading chats\" / \"Loading profile\" rehydration overlays. */\n  private async pageIsRehydrating(page: Page): Promise<boolean> {\n    return chatGptPageIsRehydrating(page);\n  }\n\n  /** Poll until the main-content rehydration overlay is gone or the timeout elapses. */\n  private async waitForRehydrationSettled(page: Page, timeoutMs: number): Promise<void> {\n    const deadline = Date.now() + timeoutMs;\n    while (await this.pageIsRehydrating(page) && Date.now() < deadline) {\n      await new Promise(resolveSleep => setTimeout(resolveSleep, 250));\n    }\n  }\n\n  private async waitForNewAssistantTurn(\n    page: Page,\n    baseline: ChatGptSubmissionBaseline,\n    deadline: number | undefined,\n    signal?: AbortSignal,\n    externalProgress?: ChatGptTurnProgressReader,\n    graceMs: number = CHATGPT_RESPONSE_DOM_GRACE_MS,\n    completionTracker?: ChatGptCompletionTracker,\n    recoverObservation?: ChatGptObservationRecovery,\n  ): Promise<ChatGptAssistantTurnBinding> {\n    let observationPage = page;\n    let observationBaseline = baseline;\n    let recoveryAttempts = 0;\n    let responseDeadline = Math.min(\n      deadline ?? Number.POSITIVE_INFINITY,\n      Date.now() + graceMs,\n    );\n    let rehydrationSince: number | undefined;\n    let runningSince: number | undefined;\n    for (;;) {\n      if (signal?.aborted) throw new DOMException(\"ChatGPT web turn aborted\", \"AbortError\");\n      if (observationPage.isClosed()) throw chatGptBrowserTabClosedError();\n      let progress = externalProgress?.snapshot();\n      if (progress?.lastProgressAt !== undefined) {\n        responseDeadline = Math.min(\n          deadline ?? Number.POSITIVE_INFINITY,\n          Math.max(responseDeadline, progress.lastProgressAt + graceMs),\n        );\n      }\n      if (deadline !== undefined && Date.now() >= deadline) {\n        throw new Error(\"ChatGPT web turn timed out\");\n      }\n      // While the temporary-chat surface rehydrates the conversation (\"Loading chats\"), the\n      // assistant turn cannot appear yet, so the deadline is paused instead of consumed. A\n      // rehydration that outlives the stall budget means the surface is stale, not merely slow.\n      if (await this.pageIsRehydrating(observationPage)) {\n        rehydrationSince ??= Date.now();\n        if (Date.now() - rehydrationSince > CHATGPT_PAGE_REHYDRATION_STALL_MS) {\n          throw new ChatGptSurfaceStaleError(\n            \"ChatGPT is still rehydrating the conversation page (Loading chats); the temporary-chat surface may be stale — retry the turn\",\n          );\n        }\n        responseDeadline = Math.min(\n          deadline ?? Number.POSITIVE_INFINITY,\n          Math.max(responseDeadline, Date.now() + graceMs),\n        );\n      } else {\n        rehydrationSince = undefined;\n      }\n      if (Date.